import axios from 'axios';

// URL до вашого API
const API_URL = 'http://localhost:3000/api'; 

// Функція для отримання книг з фільтрами
export const getBooks = (filters = {}) => {
  const params = new URLSearchParams(filters).toString(); // Конвертуємо фільтри у query string
  return axios.get(`${API_URL}/books?${params}`);
};

// Асинхронна функція для отримання відфільтрованих книг
export const getFilteredBooks = async (filters) => {
  try {
    const queryString = new URLSearchParams(filters).toString(); // Формуємо query string з фільтрів
    const response = await axios.get(`${API_URL}/books?${queryString}`);
    return response.data; // Повертаємо дані з відповіді сервера
  } catch (error) {
    console.error("Помилка завантаження книг:", error); // Лог помилок у разі проблем
    return []; // Повертаємо порожній масив у разі помилки
  }
};
